create or replace package body t010_math as
  function annuity_factor(p_rate in number, p_periods in number) return number is
  begin
    if p_rate = 0 then
      return 1 / p_periods;
    end if;
    -- The standard formula for the payment factor (which is what annuity_factor should represent here) is:
    -- P * [r * (1+r)^n] / [(1+r)^n - 1]
    -- The factor is: [r * (1+r)^n] / [(1+r)^n - 1]
    return (p_rate * power(1 + p_rate, p_periods)) / (power(1 + p_rate, p_periods) - 1);
  end annuity_factor;
end t010_math;
